using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Interop;using System.Runtime.InteropServices;using System.Windows.Automation;using Gunt.ControlCenter.Services;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Views {
 public sealed class DeveloperPopup:Window {
  readonly System.Diagnostics.Stopwatch creation=System.Diagnostics.Stopwatch.StartNew();
  readonly DesktopService service;readonly string root;readonly Action<string> navigate;readonly TextBlock feedback=new TextBlock{TextWrapping=TextWrapping.Wrap};readonly StackPanel panel=new StackPanel{Margin=new Thickness(16)};readonly Brush surface=UxTheme.Background,text=UxTheme.Text,muted=UxTheme.Muted;bool busy,ready;
  public DeveloperPopup(string directory,bool palette,Action<string> navigate=null){root=directory;service=new DesktopService(root);this.navigate=navigate;Title=palette?"GUnT_0x9 명령 팔레트":"GUnT_0x9 빠른 패널";Width=palette?680:360;Height=palette?430:Double.NaN;SizeToContent=palette?SizeToContent.Manual:SizeToContent.Height;MaxHeight=650;MinWidth=320;MinHeight=palette?350:0;Background=surface;Foreground=text;FontFamily=new FontFamily("S-Core Dream 4 Regular, Manrope, Malgun Gothic, Segoe UI");FontSize=13;UseLayoutRounding=true;SnapsToDevicePixels=true;ShowInTaskbar=false;Topmost=true;WindowStartupLocation=WindowStartupLocation.CenterScreen;Resources.MergedDictionaries.Add(UxTheme.Resources);Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};if(palette)BuildPalette();else BuildPanel();feedback.Foreground=muted;panel.Children.Add(feedback);PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape&&!busy){Close();e.Handled=true;}};SourceInitialized+=delegate{int dark=1;DwmSetWindowAttribute(new WindowInteropHelper(this).Handle,20,ref dark,4);};Loaded+=delegate{Position(palette);ready=true;};ContentRendered+=delegate{if(creation.IsRunning){creation.Stop();Gunt.ControlCenter.Infrastructure.UiPerformance.Record(root,palette?"palette-first-render":"panel-first-render",creation.Elapsed.TotalMilliseconds);}};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(busy){e.Cancel=true;feedback.Text="실행 요청 처리 중입니다. 완료 후 닫으세요.";}};Deactivated+=delegate{if(!palette&&ready&&!busy&&!IsOwnedDialogOpen())Close();};}
  bool IsOwnedDialogOpen(){return OwnedWindows.Count>0;}
  void Position(bool palette){var point=System.Windows.Forms.Cursor.Position;var screen=System.Windows.Forms.Screen.FromPoint(point);var work=screen.WorkingArea;double scale=GuntLayout.Scale(screen);var h=new WindowInteropHelper(this).Handle;int width=(int)Math.Min(Width*scale,work.Width-16),height=(int)Math.Min(ActualHeight*scale,work.Height-16);MinWidth=Math.Min(MinWidth,width/scale);MinHeight=Math.Min(MinHeight,height/scale);int x=palette?work.Left+(work.Width-width)/2:Math.Max(work.Left+8,Math.Min(point.X,work.Right-width-8));int y=palette?work.Top+(work.Height-height)/3:work.Top+8;SetWindowPos(h,IntPtr.Zero,x,y,width,height,0x14);}
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr h,int attribute,ref int value,int size);
  [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint flags);
  void Label(string value,bool secondary=false){panel.Children.Add(new TextBlock{Text=value,Foreground=secondary?muted:text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)});}
  Button Button(Panel p,string title,Action action){var b=new Button{Content=title};AutomationProperties.SetName(b,title);b.Click+=delegate{try{action();}catch(Exception e){feedback.Text="처리 실패: "+e.Message;}};p.Children.Add(b);return b;}
  void Page(string id){if(navigate!=null)navigate(id);else service.OpenControlCenter(id);Close();}
  IEnumerable<Button> PopupButtons(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);var button=child as Button;if(button!=null)yield return button;foreach(var nested in PopupButtons(child))yield return nested;}}
  void Run(Func<string> action){if(busy)return;busy=true;var buttons=PopupButtons(panel).Where(b=>b.IsEnabled).ToArray();foreach(var button in buttons)button.IsEnabled=false;feedback.Text="처리 중…";Task.Factory.StartNew(action).ContinueWith(t=>Dispatcher.BeginInvoke((Action)delegate{busy=false;foreach(var button in buttons)button.IsEnabled=true;feedback.Text=t.IsFaulted?"실행 실패: "+t.Exception.GetBaseException().Message:t.Result;}));}
  void BuildPanel(){Label("현재 프로젝트",true);ProjectEntry project=null;try{project=service.ActiveProject();Label(project.Name);Label(project.Directory,true);}catch(Exception e){Label(e.Message,true);}var actions=new WrapPanel();panel.Children.Add(actions);Button(actions,"프로젝트 선택",()=>Page("developer-setup"));foreach(var tool in new[]{new[]{"Codex","codex"},new[]{"OpenCode","opencode"},new[]{"VS Code","ide"},new[]{"폴더","folder"}}){string kind=tool[1];var launch=Button(actions,tool[0],()=>Run(()=>{var current=service.ActiveProject();if(project==null||current.Id!=project.Id||current.Directory!=project.Directory)throw new InvalidOperationException("선택 프로젝트가 변경됐습니다. 빠른 패널을 다시 열어 확인하세요.");return service.LaunchDeveloper(current,kind);}));launch.IsEnabled=project!=null;if(project==null){launch.ToolTip="프로젝트를 먼저 선택하세요.";ToolTipService.SetShowOnDisabled(launch,true);}}Button(actions,"개발 세션 시작",StartSessionQuick);panel.Children.Add(new System.Windows.Shapes.Rectangle{Height=1,Fill=UxTheme.Border,Margin=new Thickness(0,8,0,12)});Label("데스크톱 · "+service.ProfileState(),true);var desktop=new WrapPanel();panel.Children.Add(desktop);Button(desktop,"모니터 표시 / 숨김",()=>Run(()=>{service.Action("monitor-toggle");return "실제 모니터 전환 요청을 전달했습니다.";}));Button(desktop,"배경 재생 / 정지",()=>Run(()=>{service.Action("wallpaper-toggle");return "기존 배경의 수동 재생 정책 전환 요청을 전달했습니다.";}));Button(desktop,"프로필",()=>Page("profiles"));Button(desktop,"제어 센터",()=>Page("overview"));Button(desktop,"명령 팔레트",()=>{service.OpenControlCenter("palette");Close();});}
  void StartSessionQuick(){try{var p=service.ActiveProject();var prefs=service.Preferences(p);var preset=service.Sessions().Presets.FirstOrDefault(x=>x.Id==prefs.SessionPreset);if(preset==null)throw new ArgumentException("기본 개발 세션을 개발 설정에서 선택하세요.");busy=true;bool yes;try{yes=MessageBox.Show(this,service.SessionPreview(p,preset),"개발 세션 시작",MessageBoxButton.OKCancel,MessageBoxImage.Question,MessageBoxResult.Cancel)==MessageBoxResult.OK;}finally{busy=false;}if(!yes)return;bool command=false;if(preset.Actions.Any(x=>x.Enabled&&x.Kind=="command")){busy=true;try{command=MessageBox.Show(this,String.Join("\n",p.Commands??new List<string>()),"프로젝트 명령 실행 허용",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)==MessageBoxResult.Yes;}finally{busy=false;}}Run(()=>{var run=service.StartSession(p,preset,command);return run.Result+"\n"+String.Join("\n",run.Actions.Select(x=>x.ToString()));});}catch(Exception e){feedback.Text=e.Message;}}
  void BuildPalette(){var query=new TextBox{Margin=new Thickness(0,0,0,10)};AutomationProperties.SetName(query,"GUNT 명령 검색");query.ToolTip="명령·프로젝트 검색";panel.Children.Add(query);var list=new ListBox{Height=240};AutomationProperties.SetName(list,"GUNT 명령 결과");VirtualizingStackPanel.SetIsVirtualizing(list,true);VirtualizingStackPanel.SetVirtualizationMode(list,VirtualizationMode.Recycling);panel.Children.Add(list);
   var context=new TextBlock{Foreground=muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,8)};panel.Children.Add(context);
   CommandEntry[] commands=service.Commands();CommandStore commandConfig=service.CommandsConfig();var projects=service.Projects();ProjectEntry active=null;try{active=service.ActiveProject();}catch{}var preferences=projects.ToDictionary(p=>p.Id,p=>service.Preferences(p));
   list.SelectionChanged+=delegate{var entry=list.SelectedItem as CommandEntry;if(entry==null){context.Text="검색 결과가 없습니다. 프로젝트 이름이나 명령 이름을 입력하세요.";return;}var project=String.IsNullOrEmpty(entry.ProjectId)?active:projects.FirstOrDefault(p=>p.Id==entry.ProjectId);if(entry.Action=="developer"||entry.Action=="session"){DeveloperPreferences prefs=null;if(project!=null)preferences.TryGetValue(project.Id,out prefs);context.Text=project==null?"선택된 프로젝트 없음 · 개발 세팅에서 프로젝트를 선택하세요.":project.Name+" · "+(prefs==null||String.IsNullOrEmpty(prefs.WslDistribution)?"기본 WSL 배포판":prefs.WslDistribution)+"\n"+project.Directory;}else context.Text=entry.Action=="page"?"설정 화면으로 이동":entry.Action=="profile"?"작업공간 변경 미리보기":"데스크톱 작업";};
   Action filter=()=>{var timing=System.Diagnostics.Stopwatch.StartNew();try{list.ItemsSource=service.SearchCommands(query.Text,commands,commandConfig);if(list.Items.Count>0)list.SelectedIndex=0;}catch(Exception e){feedback.Text=e.Message;}finally{Gunt.ControlCenter.Infrastructure.UiPerformance.Record(root,"palette-search",timing.Elapsed.TotalMilliseconds);}};query.TextChanged+=delegate{filter();};Action execute=()=>{try{if(busy){feedback.Text="현재 실행 요청을 처리 중입니다.";return;}var command=list.SelectedItem as CommandEntry;if(command==null)return;if(command.Action=="page"){service.RememberCommand(command.Id);Page(command.Value);}else if(command.Action=="session"){StartSessionQuick();}else if(command.Action=="panel"){service.OpenControlCenter("quick-panel");Close();}else {if(command.Action=="developer"){var shown=String.IsNullOrEmpty(command.ProjectId)?active:projects.FirstOrDefault(p=>p.Id==command.ProjectId);var current=String.IsNullOrEmpty(command.ProjectId)?service.ActiveProject():service.Projects().FirstOrDefault(p=>p.Id==command.ProjectId);if(shown==null||current==null||shown.Id!=current.Id||shown.Directory!=current.Directory)throw new InvalidOperationException("프로젝트 대상이 변경됐습니다. 팔레트를 다시 열어 확인하세요.");}Run(()=>service.ExecuteCommand(command));}}catch(Exception e){feedback.Text=e.Message;}};PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Down||e.Key==Key.Up){if(list.Items.Count>0){list.SelectedIndex=Math.Max(0,Math.Min(list.Items.Count-1,list.SelectedIndex+(e.Key==Key.Down?1:-1)));list.ScrollIntoView(list.SelectedItem);}e.Handled=true;}else if(e.Key==Key.Enter){execute();e.Handled=true;}};list.MouseDoubleClick+=delegate{execute();};var a=new WrapPanel();panel.Children.Add(a);Button(a,"선택 명령 실행",execute);Button(a,"즐겨찾기 전환",()=>{var c=list.SelectedItem as CommandEntry;if(c==null)return;service.FavoriteCommand(c.Id);commands=service.Commands();commandConfig=service.CommandsConfig();filter();});Label("↑ ↓ 선택    Enter 실행    Esc 닫기",true);filter();Loaded+=delegate{query.Focus();};}
 }
}
